INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6701, 'Ruth 4:4', 'Ruth', 4, 4, '&nbsp;زما خيال دا دے چې تۀ د دې په حقله خبر شې. نو بيا، کۀ دا اخستل غواړې، نو د دې ناستو کسانو په مخکښې ووايه، او کۀ نۀ غواړې، نو هم ووايه، ځکه چې د دې اخستلو اول حق ستا دے او بيا زما.“ هغه سړى ووئيل، ”زۀ به دا واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6702, 'Ruth 4:5', 'Ruth', 4, 5, '&nbsp;بوعز ووئيل، ”ډېره ښۀ ده، کۀ تۀ د نعومى نه پټے اخلې نو ورسره روت هغه موآبۍ کونډه به هم اخلې، نو دا پټے به د مړى د خاندان په ميراث کښې راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6703, 'Ruth 4:6', 'Ruth', 4, 6, '&nbsp;هغۀ جواب ورکړو، ”نو په دې وجه زۀ بيا داسې نۀ شم کولے، زۀ خپل حق پرېږدم، کۀ تۀ يې اخستل غواړې نو وا يې خله. ځکه چې د دې مطلب دا دے چې دا به زما د بچو ميراث نۀ وى. نو هم تۀ يې واخله، زما نۀ دے په کار.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6704, 'Ruth 4:7', 'Ruth', 4, 7, '&nbsp;په هغه ورځو کښې، د اخستلو خرڅولو او د جائيداد بدلولو، دا رِواج وو چې خرڅوونکى به خپله څپلۍ وويستله او اخستونکى له به يې ورکړله. په بنى اِسرائيلو کښې د دې مطلب دا وو چې خبره پخه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6705, 'Ruth 4:8', 'Ruth', 4, 8, '&nbsp;نو کله چې سړى بوعز ته ووئيل چې، ”تۀ پټے واخله،“ هغۀ خپله څپلۍ وويستله او بوعز له يې ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6706, 'Ruth 4:9', 'Ruth', 4, 9, '&nbsp;نو بيا بوعز مشرانو او هلته نورو کسانو ته ووئيل، ”تاسو ټول ګواه اوسئ چې ما د نعومى نه ټول څيزونه واخستل چې هغه د اِلى‌مَلِک او د هغۀ د زامنو کِليون او محلون دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6707, 'Ruth 4:10', 'Ruth', 4, 10, '&nbsp;او ورسره موآبۍ روت، د محلون ښځه، زما ښځه شوه. د دې په وجه به جائيداد د مړى په خاندان کښې پاتې شى، او دا ميراث به د هغۀ د خاندان نوم د هغۀ په خلقو او د هغۀ په کلى کښې ژوندے وساتى. تاسو نن د دې خبرې ګواهان يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6708, 'Ruth 4:11', 'Ruth', 4, 11, '&nbsp;مشرانو او نورو کسانو ووئيل، ”آو، مونږ ګواهان يُو. مالِک خُدائ دې ستا ښځه د راحيل او لِياه په شان کړى، چې هغوئ د يعقوب کور آباد کړو. تۀ دې په اِفرات کښې مالدار او په بيت‌لحم کښې مشهور شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6709, 'Ruth 4:12', 'Ruth', 4, 12, '&nbsp;او د دې ځوانې ښځې نه چې مالِک خُدائ کوم بچى درکړى هغوئ دې ستا خاندان د فارص د خاندان په شان جوړه کړى، چې هغه د يهوداه او تامار زوئ وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6710, 'Ruth 4:13', 'Ruth', 4, 13, '&nbsp;نو بوعز د روت سره وادۀ وکړو او کور ته يې بوتله. مالِک خُدائ هغه بختوره کړه، او هغه اُميدواره شوه او يو زوئ يې وشو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6711, 'Ruth 4:14', 'Ruth', 4, 14, '&nbsp;ښځو نعومى ته ووئيل، ”د مالِک خُدائ ثناء ووايه چې هغۀ تا له نن نمسے درکړو چې ستا خيال وساتى. دا هلک دې په بنى اِسرائيلو کښې مشهور شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6712, 'Ruth 4:15', 'Ruth', 4, 15, '&nbsp;ستا اِنږور تا سره مينه کوى، هغې ستا دپاره د اوو زامنو نه ډېر څۀ کړى دى. اوس د هغې ماشوم پېدا شوے دے، هغه به تا له يو نوے ژوند درکړى او هغه به ستا په آخرى عُمر کښې خيال ساتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6713, 'Ruth 4:16', 'Ruth', 4, 16, '&nbsp;نو نعومى ماشوم واخستو، سينې ته يې جُخت کړو او د هغۀ خيال يې ساتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6714, 'Ruth 4:17', 'Ruth', 4, 17, '&nbsp;د ګاونډ ښځو د ماشوم نوم عوبيد کېښودو. هغوئ هر چا ته وئيل، ”د نعومى کره ماشوم شوے دے.“ عوبيد د يَسى پلار شو، چې هغه د داؤد پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6715, '1 Samuel 1:1', '1 Samuel', 1, 1, '&nbsp;يو سړے چې نوم يې القنه وو هغه راما ښار کښې اوسېدو. د هغۀ تعلق د اِفرائيم قبيلې سره وو، او د اِفرائيم د غرونو په مُلک کښې پاتې کېدو. هغه د يروحام زوئ او د اليهُو نمسے وو او هغه د توخُو د خاندان نه وو چې د صُوف د قبيلې يوه برخه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6716, '1 Samuel 1:2', '1 Samuel', 1, 2, '&nbsp;د القنه دوه ښځې وې حنه او فِننه، د فِننه بچى وُو خو د حنه نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6717, '1 Samuel 1:3', '1 Samuel', 1, 3, '&nbsp;القنه به هر کال د راما نه تلو چې په سيلا کښې د ربُ الافواج عبادت وکړى او قربانى ورته پېش کړى، چرته چې د عيلى دوه زامن حُفنى او فينحاس د مالِک خُدائ اِمامان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6718, '1 Samuel 1:4', '1 Samuel', 1, 4, '&nbsp;هر ځل چې القنه خپله قربانى پېش کوله نو هغۀ به د غوښې يوه برخه فِننې له او يوه يوه برخه به يې د هغې هر بچى له ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6719, '1 Samuel 1:5', '1 Samuel', 1, 5, '&nbsp;هغۀ د حنه سره ډېره مينه کوله نو ځکه هغې له يې يو په دوه برخه ورکوله، اګر چې مالِک خُدائ هغه شنډه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6720, '1 Samuel 1:6', '1 Samuel', 1, 6, '&nbsp;د هغې بنې فِننې به هغه رټله او سپکوله به يې، ځکه چې مالِک خُدائ هغه شنډه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6721, '1 Samuel 1:7', '1 Samuel', 1, 7, '&nbsp;هر کال به داسې کېدل، هغوئ به چې کله هم د مالِک خُدائ کور ته لاړل نو فِننې به حنه دومره خفه کړه چې هغې به ژړل او خوراک به يې نۀ کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6722, '1 Samuel 1:8', '1 Samuel', 1, 8, '&nbsp;د هغې خاوند القنه به ترې نه تپوس کولو، ”حنه تۀ ولې ژاړې؟ تۀ ولې خوراک نۀ کوې؟ تۀ هر وخت ولې دومره خفه يې؟ زۀ ستا دپاره د لسو زامنو نه ښۀ نۀ يم څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6723, '1 Samuel 1:11', '1 Samuel', 1, 11, '&nbsp;حنه يو پوخ لوظ وکړو، ”اے، ربُ الافواجه، کۀ چرې تۀ په ما غمزپلې رحم وکړې او زما دُعا قبوله کړې او ما له يو زوئ راکړې، نو زۀ دا وعده کوم چې هغه به د ټول عُمر دپاره تا ته د نذير په حيثيت وقف کړم او د هغۀ د وقف کېدو نښه به دا وى چې وېښتۀ به يې هيڅکله هم کل نۀ کړے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6724, '1 Samuel 1:12', '1 Samuel', 1, 12, '&nbsp;حنه تر ډېر وخته پورې مالِک خُدائ ته سوال کولو او عيلى د هغې شونډو ته کتل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6725, '1 Samuel 1:13', '1 Samuel', 1, 13, '&nbsp;هغې په خاموشۍ سره دُعا کوله، د هغې شونډې خوځېدلې، خو آواز ترې نه نۀ وتلو. نو د عيلى دا خيال وو چې هغه په نشه کښې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6726, '1 Samuel 1:14', '1 Samuel', 1, 14, '&nbsp;او هغې ته يې ووئيل، ”ترڅو پورې به تۀ نشه بازى کوې، د ميو نه ځان خلاص کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6727, '1 Samuel 1:15', '1 Samuel', 1, 15, '&nbsp;هغې ورته په جواب کښې ووئيل، ”صاحِبه، زۀ په نشه کښې نۀ يم. ما نۀ مے او نۀ شراب څښلى دى، زۀ سخته پرېشانه يم او ما دُعا کوله او خپل تکليفونه مې مالِک خُدائ ته بيانول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6728, '1 Samuel 1:16', '1 Samuel', 1, 16, '&nbsp;ما يوه بې‌کاره ښځه مۀ ګڼه. ما هم داسې دُعا کوله ځکه چې زۀ په سخت غم آخته يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6729, '1 Samuel 1:17', '1 Samuel', 1, 17, '&nbsp;عيلى ورته ووئيل، ”په خېر لاړه شه او چې څۀ دې غوښتى وى نو د بنى اِسرائيلو خُدائ پاک دې هغه تا له درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6730, '1 Samuel 1:18', '1 Samuel', 1, 18, '&nbsp;هغې جواب ورکړو، ”په ما باندې د رحم نظر وکړه. بيا هغه لاړه، خوراک يې وکړو او پرېشانى يې ختمه شوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6731, '1 Samuel 1:19', '1 Samuel', 1, 19, '&nbsp;په ورپسې سحر القنه او د هغۀ خاندان وختى پاڅېدل او د مالِک خُدائ د عبادت نه پس هغوئ په راما کښې واپس خپل کور ته لاړل. القنه د خپلې ښځې حنه سره څملاستو او مالِک خُدائ د هغې دُعا قبوله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6732, '1 Samuel 1:20', '1 Samuel', 1, 20, '&nbsp;چې حنه اُميدواره شوه او يو زوئ يې پېدا شو نو سموئيل نوم يې ورباندې کېښودو او وې وئيل، ”ما دے د مالِک خُدائ نه غوښتے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6733, '1 Samuel 1:21', '1 Samuel', 1, 21, '&nbsp;هغه وخت بيا راغلو چې القنه او د هغۀ خاندان سيلا ته لاړل او مالِک خُدائ ته يې کلنى نذرانه او د منښتې نذرانه پېش کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6734, '1 Samuel 1:22', '1 Samuel', 1, 22, '&nbsp;خو دا ځل حنه لا نۀ ړه. هغې خپل خاوند ته ووئيل، ”ماشوم چې کله د مور د تى نه منعې شى نو زۀ به يې د مالِک خُدائ کور ته بوځم، چرته به چې هغه د نذير په حيثيت ټول عُمر تېروى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6735, '1 Samuel 1:23', '1 Samuel', 1, 23, '&nbsp;القنه ورته ووئيل، ”ټيک ده، څۀ چې درته ښۀ ښکارى نو هم هغه وکړه، تر هغې پورې په کور کښې پاتې شه چې کله هغه د مور د تى نه منعې شى او مالِک خُدائ دې وکړى چې ستا وعده پوره شى.“ نو حنه په کور کښې ايساره وه او خپل بچى له يې تے ورکولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6736, '1 Samuel 1:24', '1 Samuel', 1, 24, '&nbsp;چې کله هغه د مور د تى نه منعې شو نو هغه يې سيلا ته بوتلو، ورسره يې يو درې کلن سخے، لس کېلو اوړۀ او يوه ډکه مشکيزه د ميو يوړه. او هغې په سيلا کښې د مالِک خُدائ کور ته سموئيل بوتلو اګر چې هغه لا وړوکے ماشوم وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6737, '1 Samuel 1:25', '1 Samuel', 1, 25, '&nbsp;چې کله هغوئ سخے حلال کړو نو هغوئ ماشوم عيلى له بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6738, '1 Samuel 1:26', '1 Samuel', 1, 26, '&nbsp;حنه هغۀ ته ووئيل، ”صاحِبه، بې‌ادبى دې معاف وى، زۀ تا ته ياده يم څۀ؟ زۀ هغه ښځه يم چې دلته ولاړه وم مالِک خُدائ ته مې سوال کولو او تا وليدم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6739, '1 Samuel 1:27', '1 Samuel', 1, 27, '&nbsp;ما د هغۀ نه د دې ماشوم سوال وکړو او چې ما ترې نه د څۀ سوال کړے وو هغه يې ما له راکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6740, '1 Samuel 1:28', '1 Samuel', 1, 28, '&nbsp;نو زۀ دے مالِک خُدائ ته وقف کوم. تر کومې پورې چې دے ژوندے وى نو د مالِک خُدائ به وى.“ بيا هغوئ هلته د مالِک خُدائ عبادت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6741, '1 Samuel 2:1', '1 Samuel', 2, 1, '&nbsp;حنه دُعا وکړه او وې وئيل، ”مالِک خُدائ زما زړۀ د خوشحالۍ نه ډک کړے دے، هغۀ چې څۀ کړى دى په هغې باندې زۀ څومره خوشحاله يم. زۀ په خپلو دشمنانو پورې خاندم زۀ څومره خوشحاله يم ځکه چې خُدائ پاک زما مدد کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6742, '1 Samuel 2:2', '1 Samuel', 2, 2, '&nbsp;د مالِک خُدائ په شان هيڅ څوک مقدس نشته، د هغۀ په شان بل څوک نشته، زمونږ د خُدائ پاک په شان حِفاظت کوونکے نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6743, '1 Samuel 2:3', '1 Samuel', 2, 3, '&nbsp;لوئې لافې وهل بس کړئ، د غرور خبرې د خولې نه مۀ راوباسئ. ځکه چې مالِک خُدائ يو داسې خُدائ پاک دے چې هغه پوهيږى، او هغه د خلقو د هر عمل عدالت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6744, '1 Samuel 2:4', '1 Samuel', 2, 4, '&nbsp;د تکړه فوجيانو ليندې ماتې شوې دى، خو کمزورى تکړه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6745, '1 Samuel 2:5', '1 Samuel', 2, 5, '&nbsp;کومو خلقو له چې يو ځل خوراک ورکړے شوے وو نو هغوئ اوس د خوراک دپاره خپل ځانونه مزدوران کړل، خو چې څوک اوږى وُو د هغوئ لوږه ختمه شوه. د شنډې ښځې اووۀ بچى شوى دى، خو د ډېرو بچو مور غمژنه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6746, '1 Samuel 2:6', '1 Samuel', 2, 6, '&nbsp;مالِک خُدائ مړۀ کول او ژوندى کول کوى، هغه خلق قبر ته لېږى او واپس يې راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6747, '1 Samuel 2:7', '1 Samuel', 2, 7, '&nbsp;هغه څوک غريب کوى او څوک مالداره کوى، هغه څوک لاندې کوى او څوک اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6748, '1 Samuel 2:8', '1 Samuel', 2, 8, '&nbsp;هغه غريب د خاورې نه راوچتوى او ضرورتمند د ايرو د ډېرى نه اوچتوى، او د شهزادګانو مرتبه ورکوى او د عزت په ځايونو کښې يې کښېنوى. د زمکې بنيادونه د مالِک خُدائ دى، په دې باندې هغۀ دُنيا ودرولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6749, '1 Samuel 2:9', '1 Samuel', 2, 9, '&nbsp;هغه د خپلو وفادارو خلقو ژوند بچ کوى، خو بدعمله په تيارۀ کښې ورکيږى، سړے په خپل طاقت باندې نۀ بريالے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6750, '1 Samuel 2:10', '1 Samuel', 2, 10, '&nbsp;د مالِک خُدائ دشمنان به تباه شى، هغه به د هغوئ خِلاف د آسمان د تندر په شان شى. مالِک خُدائ به د ټولې دُنيا عدالت کوى، هغه به خپل بادشاه له طاقت ورکړى، هغه به خپل خوښ کړے شوے بادشاه بريالے کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6751, '1 Samuel 2:11', '1 Samuel', 2, 11, '&nbsp;بيا القنه واپس په راما کښې کور ته لاړو، خو سموئيل په سيلا کښې پاتې شو او د عيلى اِمام د مشرۍ لاندې يې د مالِک خُدائ خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6752, '1 Samuel 2:12', '1 Samuel', 2, 12, '&nbsp;د عيلى زامن بد عمله کسان وُو. هغوئ مالِک خُدائ ته هيڅ توجو ورنۀ کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6753, '1 Samuel 2:13', '1 Samuel', 2, 13, '&nbsp;او نۀ يې د هغه اصُولو خيال وساتلو چې د اِمامانو د برخې په حقله وُو. او کله به چې چا يوه نذرانه پېش کوله او چې غوښه به لا پخېدله نو د اِمام نوکر به د يو درې غاښى سره راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6754, '1 Samuel 2:14', '1 Samuel', 2, 14, '&nbsp;هغۀ به درې غاښے د پخلى لوښى ته ورننويستلو او چې درې غاښى به څۀ هم راوويستل نو هغه به د اِمام وُو. د هغه ټولو بنى اِسرائيلو سره هم داسې سلوک وشو چې د قربانۍ پېش کولو دپاره سيلا ښار ته راغلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6755, '1 Samuel 2:15', '1 Samuel', 2, 15, '&nbsp;د دې نه علاوه، وازګه به هم لا نۀ وه لرې کړے شوې او نۀ به سوزولے شوې وه چې د اِمام نوکر به راغلو او چې چا به نذرانه پېش کوله نو هغۀ ته به يې وئيل، ”ما له لږه غوښه راکړه چې اِمام له يې وريته کړم، هغه به ستاسو پخه شوې غوښه نۀ قبلوى، صِرف کچه غوښه قبلوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6756, '1 Samuel 2:16', '1 Samuel', 2, 16, '&nbsp;کۀ هغه کس به ورته ووئيل، ”راځئ چې هغه وکړُو چې څۀ صحيح وى او اول وازګه وسوزوو، بيا چې دې څۀ خوښ وى نو هغه واخله.“ خو د اِمام نوکر به ورته ووئيل، ”نه، اوس دا ما له راکړه، کۀ نۀ راکوې، نو زۀ به يې په زور اخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6757, '1 Samuel 2:17', '1 Samuel', 2, 17, '&nbsp;د عيلى د زامنو دا ګناه د مالِک خُدائ په نظر کښې ډېره لويه وه، ځکه چې هغوئ د مالِک خُدائ د نذرانو دومره بې‌عزتى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6758, '1 Samuel 2:18', '1 Samuel', 2, 18, '&nbsp;په دې دوران کښې سموئيل هلک د مالِک خُدائ خِدمت جارى وساتلو، د لټې يو مقدس پېش بند به يې اغوستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6759, '1 Samuel 2:19', '1 Samuel', 2, 19, '&nbsp;د هغۀ مور به هر کال يوه وړه چُوغه جوړوله او چې هغه د خپل خاوند سره کلنى نذرانه پېش کولو له تله نو چُوغه به يې وروړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6760, '1 Samuel 2:20', '1 Samuel', 2, 20, '&nbsp;نو عيلى به د القنه او د هغۀ د ښځې دپاره برکت غوښتو او القنه ته به يې فرمائيل، ”مالِک خُدائ دې تا له د دې ښځې نه نور بچى درکړى چې د هغۀ ځائ ونيسى چې کوم تا مالِک خُدائ ته وقف کړے دے.“ د هغې نه پس به هغوئ واپس کور ته تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6761, '1 Samuel 2:21', '1 Samuel', 2, 21, '&nbsp;مالِک خُدائ حنه له برکت ورکړو او د هغې نور درې زامن او دوه لوڼه پېدا شوې. سموئيل هلک د مالِک خُدائ په خِدمت کښې لوئ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6762, '1 Samuel 2:22', '1 Samuel', 2, 22, '&nbsp;عيلى اوس ډېر بوډا شوے وو. هغۀ د هغه هر څۀ په حقله اورېدل چې د هغۀ زامنو د بنى اِسرائيلو سره کول او دا چې هغوئ د هغه ښځو سره هم څملاستل چا چې د مالِک خُدائ د حضور خېمې د دروازې په خولۀ کښې خدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6763, '1 Samuel 2:23', '1 Samuel', 2, 23, '&nbsp;نو هغۀ هغوئ ته ووئيل، ”تاسو دا کارونه ولې کوئ؟ تاسو چې کوم بد کوئ هر سړے د هغې په حقله ما ته وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6764, '1 Samuel 2:24', '1 Samuel', 2, 24, '&nbsp;بس کړئ، زما زامنو، زۀ خبر شوے يم چې د مالِک خُدائ د خلقو په مينځ کښې يو خراب خبر خوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6765, '1 Samuel 2:25', '1 Samuel', 2, 25, '&nbsp;کۀ يو سړے د بل چا خِلاف ګناه وکړى، نو خُدائ پاک ته د هغۀ دپاره سوال کېدے شى خو کۀ يو سړے د مالِک خُدائ خِلاف ګناه وکړى نو د هغۀ دپاره هيڅ څوک هم د رحم سوال نۀ شى کولے.“ خو هغوئ خپل پلار ته غوږ ونۀ نيولو، ځکه چې مالِک خُدائ د هغوئ د وژلو فېصله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6766, '1 Samuel 2:26', '1 Samuel', 2, 26, '&nbsp;سموئيل هلک غټېدو او د مالِک خُدائ او د خلقو عزت يې وموندو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6767, '1 Samuel 2:27', '1 Samuel', 2, 27, '&nbsp;عيلى ته د مالِک خُدائ نه د دې پېغام سره د مالِک خُدائ نه يو پېغمبر راغلو، ”کله چې ستا پلار نيکۀ هارون او د هغۀ خاندان د مِصر د فِرعون غلامان وُو، نو ما خپل ځان هارون ته څرګند کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6768, '1 Samuel 2:28', '1 Samuel', 2, 28, '&nbsp;ما د بنى اِسرائيلو د ټولو قبيلو نه د هغۀ خاندان خوښ کړو چې زما اِمامان شى، چې د قربان‌ګاه سره خِدمت کوى، خوشبوئى سوزوى او زما په حضور کښې پېش بند اغوندى. او چې په قربان‌ګاه باندې کومې نذرانې سوزولے شى نو د هغې د اخستلو حق مې ورله ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6769, '1 Samuel 2:29', '1 Samuel', 2, 29, '&nbsp;نو بيا، تاسو ولې د هغه نذرانو او قربانو لالچ کوئ چې زۀ يې د خپلو خلقو نه غواړم؟ عيلى، تۀ ولې زما نه زيات د خپلو زامنو عزت کوې چې هغوئ دې پرېښى دى چې زما خلق ما ته کومې قربانۍ پېش کوى چې د هغې په ټولو ښو حِصو باندې خپل ځانونه څورب کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6770, '1 Samuel 2:30', '1 Samuel', 2, 30, '&nbsp;ما، مالِک خُدائ د بنى اِسرائيلو خُدائ پاک په تېره زمانه کښې دا وعده وکړه چې ستاسو خاندان او قبيله به د ټولو وختونو دپاره د اِمامانو په توګه زما خِدمت کوى. خو اوس زۀ دا وايم چې نور به داسې نۀ وى بلکې د دې په ځائ، څوک چې زما عزت کوى نو زۀ به د هغوئ عزت کوم او چې څوک زما بې‌عزتى کوى نو زۀ به د هغوئ سپکاوے کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6771, '1 Samuel 2:31', '1 Samuel', 2, 31, '&nbsp;واوره، هغه وخت راروان دے چې زۀ به ستا د خاندان او قبيلې ټول زلمى ووژنم، نو ستا په خاندان کښې به داسې يو سړے هم نۀ وى چې بوډاتوب ته ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6772, '1 Samuel 2:32', '1 Samuel', 2, 32, '&nbsp;تۀ به په تکليف کړے شې او هغه ټولو برکتونو ته به د ارمان سره ګورې چې زۀ يې نورو بنى اِسرائيلو له ورکوم، خو ستا په خاندان کښې به هيڅ څوک هم تر بوډاتوب پورې ژوندے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6773, '1 Samuel 2:33', '1 Samuel', 2, 33, '&nbsp;خو چې څوک ژوندى پاتې شى، نو هغوئ به په پرېشانۍ او غم آخته شى او د هغوئ نور ټول اولاد به په يو سخت مرګ مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6774, '1 Samuel 2:34', '1 Samuel', 2, 34, '&nbsp;کله چې ستا دوه زامن حُفنى او فينحاس دواړه په يوه ورځ مړۀ شى، نو دا به تاسو ته ثابِته شى چې ما چې هر څۀ وئيلى وُو نو هغه رښتيا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6775, '1 Samuel 2:35', '1 Samuel', 2, 35, '&nbsp;زۀ به يو اِمام خوښ کړم چې هغه به زما وفادار وى او چې څۀ زۀ غواړم نو هغه هر څۀ به کوى. زۀ به هغۀ له اولاد ورکړم، چې هغوئ به همېشه زما د خوښ شوى بادشاه په حضور کښې خِدمت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6776, '1 Samuel 2:36', '1 Samuel', 2, 36, '&nbsp;ستا د اولاد چې کوم کس هم ژوندے پاتې وى نو هغه به هغه اِمام له ځى او د هغۀ نه به پېسې او خوراک غواړى او دا سوال به ورته کوى چې ما د اِمامانو سره منظور کړه، نو چې ما ته يوه نوړۍ روټۍ مِلاو شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6777, '1 Samuel 3:1', '1 Samuel', 3, 1, '&nbsp;په هغه ورځو کښې، کله چې سموئيل هلک د عيلى د لارښودنې لاندې د مالِک خُدائ خِدمت کولو، د مالِک خُدائ وحى نازلېدل کم شوى وُو او د هغۀ پېغام څرګندېدل بلکل کم شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6778, '1 Samuel 3:2', '1 Samuel', 3, 2, '&nbsp;يوه شپه عيلى چې اوس د هغۀ نظر ډېر کمزورے شوے وو په خپله کوټه کښې ملاست وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6779, '1 Samuel 3:3', '1 Samuel', 3, 3, '&nbsp;د سحر نه مخکښې، چې ډيوه تر اوسه پورې بلېدله او سموئيل د مالِک خُدائ په کور کښې ملاست وو، چرته چې د خُدائ پاک د لوظ صندوق وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6780, '1 Samuel 3:4', '1 Samuel', 3, 4, '&nbsp;مالِک خُدائ سموئيل ته آواز وکړو. سموئيل وفرمائيل، ”زۀ دا يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6781, '1 Samuel 3:5', '1 Samuel', 3, 5, '&nbsp;او عيلى له يې منډه کړه او ورته يې وفرمائيل، ”زۀ راغلمه، تا ما ته آواز وکړو.“ خو عيلى ورته ووئيل، ”ما خو تا ته آواز نۀ دے کړے، لاړ شه او څمله.“ نو سموئيل لاړو او څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6782, '1 Samuel 3:6', '1 Samuel', 3, 6, '&nbsp;مالِک خُدائ سموئيل ته بيا آواز وکړو، ”سموئيله.“ نو سموئيل پاڅېدو، عيلى له لاړو او ورته يې وفرمائيل، ”تا ما ته آواز وکړو او زۀ راغلم.“ خو عيلى ورته ووئيل، ”زما زويه، ما خو تا ته آواز نۀ دے کړے، بيا لاړ شه او څمله.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6783, '1 Samuel 3:7', '1 Samuel', 3, 7, '&nbsp;خو هلک ته پته ونۀ لګېده چې دا مالِک خُدائ وو، ځکه چې د دې نه مخکښې مالِک خُدائ هيڅکله هم د هغۀ سره خبرې نۀ وې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6784, '1 Samuel 3:8', '1 Samuel', 3, 8, '&nbsp;مالِک خُدائ سموئيل ته په درېم ځل آواز وکړو، هغه پاڅېدو، عيلى له لاړو او ورته يې وفرمائيل، ”تا ما ته آواز وکړو او زۀ راغلم.“ نو عيلى ته پته ولګېده چې هغه مالِک خُدائ وو چا چې هلک ته آواز کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6785, '1 Samuel 3:9', '1 Samuel', 3, 9, '&nbsp;نو عيلى سموئيل ته وفرمائيل، ”لاړ شه او څمله، او کۀ هغۀ تا ته بيا آواز وکړو، نو ورته ووايه، مالِکه خُدايه، ستا بنده يې اورى.“ نو سموئيل لاړو او په خپل ځائ کښې څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6786, '1 Samuel 3:10', '1 Samuel', 3, 10, '&nbsp;نو مالِک خُدائ راغلو او هلته ودرېدو او د مخکښې په شان يې ورته آواز وکړو، ”سموئيله، سموئيله.“ سموئيل ورته ووئيل، ”وفرمائى، ستا بنده يې اورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6787, '1 Samuel 3:11', '1 Samuel', 3, 11, '&nbsp;مالِک خُدائ هغۀ ته وفرمائيل، ”ګوره، زۀ په بنى اِسرائيلو کښې داسې څۀ کوم چې هغه به دومره سخت وى چې څوک يې واورى نو حېران به شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6788, '1 Samuel 3:12', '1 Samuel', 3, 12, '&nbsp;تر اوسه پورې چې ما د عيلى او د هغۀ د خاندان خِلاف څۀ هم وئيل نو په هغه ورځ به هغه هر څۀ وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6789, '1 Samuel 3:13', '1 Samuel', 3, 13, '&nbsp;ما هغۀ ته مخکښې وئيلى دى چې زۀ د هغۀ خاندان له د تل دپاره سزا ورکوم ځکه چې د هغۀ زامنو زما خِلاف خرابې خبرې کړې دى. عيلى ته پته وه چې هغوئ داسې کول، خو هغوئ يې نۀ منع کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6790, '1 Samuel 3:14', '1 Samuel', 3, 14, '&nbsp;نو ما دا قسم کړے دے چې د دې سختې ګناه د لرې کولو دپاره به هيڅ قربانى او نذرانه د عيلى د خاندان دپاره کافى نۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6791, '1 Samuel 3:15', '1 Samuel', 3, 15, '&nbsp;سموئيل تر سحره پورې ملاست وو، بيا هغه پاڅېدو او د مالِک خُدائ د کور دروازې يې کولاو کړې. هغه د دې نه يرېدلو چې عيلى ته د دې پېغام د څرګندېدو په حقله ووائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6792, '1 Samuel 3:16', '1 Samuel', 3, 16, '&nbsp;عيلى ورته آواز وکړو، ”زما زويه، سموئيله.“ هغۀ ورته وفرمائيل، ”زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6793, '1 Samuel 3:17', '1 Samuel', 3, 17, '&nbsp;عيلى ترې نه تپوس وکړو، ”مالِک خُدائ تا ته څۀ وفرمائيل؟ زما نه يوه خبره هم مۀ پټوه. خُدائ پاک به تا له سخته سزا درکړى کۀ تا ما ته هغه هر څۀ ونۀ فرمائيل چې څۀ درته هغۀ فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6794, '1 Samuel 3:18', '1 Samuel', 3, 18, '&nbsp;نو سموئيل ورته هغه هر څۀ وفرمائيل، هغۀ ترې نه يوه خبره پټه ونۀ ساتله. عيلى وفرمائيل، ”هغه مالِک خُدائ دے، هغۀ ته چې څۀ ښۀ ښکارى نو هم هغه به وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6795, '1 Samuel 3:19', '1 Samuel', 3, 19, '&nbsp;چې سموئيل غټېدو، مالِک خُدائ د هغۀ مل وو او د مالِک خُدائ هغه ټولې پېشګويانې پوره کېدې کومې چې سموئيل کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6796, '1 Samuel 3:20', '1 Samuel', 3, 20, '&nbsp;نو د هغه مُلک د يو سر نه تر بل سره پورې، ټولو بنى اِسرائيلو ته پته ولګېده چې سموئيل په حقيقت کښې د مالِک خُدائ پېغمبر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6797, '1 Samuel 3:21', '1 Samuel', 3, 21, '&nbsp;مالِک خُدائ به په خپله په سيلا کښې راڅرګندېدو، چرته چې هغه سموئيل ته څرګند شوے وو او د هغۀ سره يې خبرې کړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6798, '1 Samuel 4:1', '1 Samuel', 4, 1, '&nbsp;ټول بنى اِسرائيليان د سموئيل د خبرو نه خبر شول. نو فلستيان د بنى اِسرائيلو خِلاف جنګ دپاره راغونډ شول او بنى اِسرائيليان هم د هغوئ سره جنګېدو دپاره راووتل. بنى اِسرائيلو په اِبن‌عزر کښې او فلستيانو په افيق کښې خپلې خېمې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6799, '1 Samuel 4:2', '1 Samuel', 4, 2, '&nbsp;فلستيانو حمله وکړه او د يوې لوئې جګړې نه پس هغوئ بنى اِسرائيلو له شکست ورکړو او تقريباً څلور زره سړى يې د جنګ په مېدان کښې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6800, '1 Samuel 4:3', '1 Samuel', 4, 3, '&nbsp;کله چې هغه ژوندى پاتې شوى کسان واپس خېمو ته راغلل، نو د بنى اِسرائيلو مشرانو ووئيل، ”مالِک خُدائ فلستيان ولې پرېښودل چې مونږ له شکست راکړى؟ ځئ چې لاړ شُو او د سيلا نه د مالِک خُدائ د لوظ صندوق راوړُو، نو دا به زمونږ سره ځى او مونږ به د خپلو دشمنانو نه بچ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');